#pragma once
#include "kstationNumericDisplayTask.h"
#include "kstationNativeLcdText.h"
namespace kstation {
class NativeNumericDisplay final {
 using T=NumericDisplayTask;using K=T::Kind;using S=T::Stage;
public:
 struct CodeRange{uint32_t begin,end;};inline static constexpr std::array<CodeRange,3>CodeRanges{{{0x12b6,0x132c},{0x1374,0x1398},{0x23b2,0x23c2}}};
 bool active()const{return depth_||lcd_.active();}void reset(){depth_=0;lcd_.reset();steps_=0;}uint64_t steps()const{return steps_;}static bool candidate(unsigned at){for(auto r:CodeRanges)if(at>=r.begin&&at<r.end)return true;return false;}
 bool step(Stage1Cpu&c){if(midi_projection::blocked(c))return false;auto at=unsigned(c.getPC());if(NativeLcdText::candidate(at)||NativeFlashState::candidate(at)){if(!lcd_.step(c))return false;++steps_;return true;}
  if(!depth_||boundary(jobs_[depth_-1])!=at){K k;if(at==0x12b6)k=K::ZeroTwo;else if(at==0x12de)k=K::SpaceTwo;else if(at==0x1306)k=K::SpaceThree;else if(at==0x23b2)k=K::String;else if(at==0x1374){if(uint8_t(c.reg8(2))<1||uint8_t(c.reg8(2))>3)return false;k=K::Format;}else return false;if(depth_==jobs_.size())throw std::logic_error("Native K numeric capacity");jobs_[depth_++]=T{k,uint8_t(c.reg8(8)),uint8_t(c.reg8(2)),uint8_t(c.reg8(10)),uint32_t(c.reg32(1))};}
  auto&t=jobs_[depth_-1];if(t.awaiting())t.resume();if(at!=boundary(t))throw std::logic_error("Native K numeric boundary");if(c.pending_irqs)c.read8(0xfffff2);auto len=bytes(t);auto cr=credits(t,c,len);auto cost=t.nextClocks(cr);auto begin=c.cycles;c.fetchClocks(len);c.pc=c.makepc(at+1);project(t,c);
  t.advanceBefore(cost,cr,[&](unsigned address){c.reg8(14)=c.read8(int(address));++c.reg32(1);val(c,c.reg8(14));c.clockI(2);return uint8_t(c.reg8(14));},[&](unsigned address,unsigned value){auto r=t.stage()==S::Digit?0:10;c.write8(int8_t(value),int(address));val(c,c.reg8(r));});
  if(c.cycles-begin!=cost)throw std::logic_error("Native K numeric clocks differ");if(t.complete())--depth_;else if(!t.awaiting())c.pc=c.makepc(boundary(t));++steps_;return true;}
private:
 static void val(Stage1Cpu&c,int v){midi_projection::val(c,v);}static void push(Stage1Cpu&c,unsigned r,bool word){c.setSP(c.getSP()-(word?2:4));if(word)c.write16(c.reg16(r),int(c.getSP()));else c.write32(c.reg32(r),int(c.getSP()));val(c,word?c.reg16(r):c.reg32(r));c.clockI(2);}static void pop(Stage1Cpu&c,unsigned r,bool word){if(word)c.reg16(r)=int16_t(c.read16(int(c.getSP())));else c.reg32(r)=int32_t(c.read32(int(c.getSP())));c.setSP(c.getSP()+(word?2:4));val(c,word?c.reg16(r):c.reg32(r));c.clockI(2);}
 static unsigned boundary(const T&t){auto k=t.kind();unsigned base=k==K::ZeroTwo?0x12b6:k==K::SpaceTwo?0x12de:0x1306;bool three=k==K::SpaceThree;switch(t.stage()){case S::RetainValue:return base;case S::RetainPointer:return base+2;case S::RetainScratch:return base+6;case S::Width:return base+10;case S::Padding:return base+12;case S::FormatChild:return base+14;case S::BindString:return base+(three?16:18);case S::StringChild:return base+(three?22:24);case S::RestoreScratch:return base+(three?26:28);case S::RestorePointer:return base+(three?30:32);case S::RestoreValue:return base+(three?34:36);case S::Return:return k==K::Format?0x1396:k==K::String?0x23c0:base+(three?36:38);case S::BindBuffer:return 0x1374;case S::Fill:return 0x137a;case S::AdvanceFill:return 0x137c;case S::DecrementFill:return 0x137e;case S::RepeatFill:return 0x1380;case S::ClearTerminator:return 0x1382;case S::Terminate:return 0x1384;case S::Radix:return 0x1386;case S::ClearHigh:return 0x1388;case S::Divide:return 0x138a;case S::Ascii:return 0x138c;case S::Backtrack:return 0x138e;case S::Digit:return 0x1390;case S::TestQuotient:return 0x1392;case S::RepeatDigits:return 0x1394;case S::RetainCharacter:return 0x23b2;case S::ReadCharacter:return 0x23b4;case S::SelectEnd:return 0x23b6;case S::CharacterChild:return 0x23b8;case S::RepeatString:return 0x23bc;case S::RestoreCharacter:return 0x23be;default:return 0;}}
 static unsigned bytes(const T&t){switch(t.stage()){case S::RetainPointer:case S::RetainScratch:case S::RestoreScratch:case S::RestorePointer:case S::StringChild:case S::CharacterChild:return 4;case S::BindString:case S::BindBuffer:return 6;case S::FormatChild:return t.kind()==K::SpaceThree?2:4;default:return 2;}}
 static unsigned bus(unsigned at,unsigned n,int last){unsigned cost=0;for(unsigned i=0;i<n;++i){auto a=(at+i)&0xffffff;if(a<0x400000||(a>=0xfffd10&&a<0xffffa0)){if((last&1)||a!=unsigned(last|1))cost+=a<0x400000?3:1;last=int(a);}else{cost+=a>=0xffffa0?1:3;last=-1;}}return cost;}
 static FlashCredits credits(const T&t,const Stage1Cpu&c,unsigned len){FlashCredits cr;int last=int(c.getPC()+len-1);cr.pushLong=8+bus(c.getSP()-4,4,c.writeHistory());cr.popLong=8+bus(c.getSP(),4,last);cr.pushWord=5+bus(c.getSP()-2,2,c.writeHistory());cr.popWord=5+bus(c.getSP(),2,last);cr.call=8+bus(c.getSP()-4,4,c.writeHistory());cr.shortCall=3+bus(c.getSP()-4,4,c.writeHistory());cr.ret=5+bus(c.getSP(),4,last);cr.read=bus(t.pointer(),1,last);cr.write=bus(t.pointer(),1,c.writeHistory());return cr;}
 static void project(const T&t,Stage1Cpu&c){auto s=t.stage();switch(s){case S::RetainValue:push(c,0,true);break;case S::RetainPointer:push(c,1,false);break;case S::RetainScratch:push(c,2,false);break;case S::Width:c.reg8(2)=t.kind()==K::SpaceThree?3:2;val(c,c.reg8(2));break;case S::Padding:c.reg8(10)=t.kind()==K::ZeroTwo?0x30:0x20;val(c,c.reg8(10));break;case S::FormatChild:midi_projection::call(c,0x1374,boundary(t)+(t.kind()==K::SpaceThree?2:4),t.kind()!=K::SpaceThree);break;case S::BindString:case S::BindBuffer:c.reg32(1)=0xfffe3e;val(c,c.reg32(1));break;case S::StringChild:midi_projection::call(c,0x23b2,boundary(t)+4,true);break;case S::RestoreScratch:pop(c,2,false);break;case S::RestorePointer:pop(c,1,false);break;case S::RestoreValue:pop(c,0,true);break;case S::Return:midi_projection::ret(c);break;
 case S::AdvanceFill:{int old=c.reg32(1),v=old+1;val(c,v);if((~old&v)&int(0x80000000))c.ccr|=2;c.reg32(1)=v;break;}case S::DecrementFill:{int old=c.reg8(2),v=old-1;val(c,v);if((old&~v)&128)c.ccr|=2;c.reg8(2)=int8_t(v);break;}case S::ClearTerminator:c.reg8(10)=0;val(c,0);break;case S::Radix:c.reg8(10)=10;val(c,10);break;case S::ClearHigh:c.reg8(0)=0;c.ccr=uint8_t((c.ccr&~0x2f)|4);break;case S::Divide:{unsigned v=uint16_t(c.reg16(0));c.ccr&=uint8_t(~12);c.reg8(8)=int8_t(v/10);c.reg8(0)=int8_t(v%10);c.clockI(12);break;}case S::Ascii:c.reg8(0)=int8_t(midi_projection::arithmetic(c,uint8_t(c.reg8(0)),0x30,8,false));break;case S::Backtrack:{int old=c.reg32(1),v=old-1;val(c,v);if((old&~v)&int(0x80000000))c.ccr|=2;c.reg32(1)=v;break;}case S::TestQuotient:val(c,c.reg8(8));break;case S::RetainCharacter:push(c,6,true);break;case S::CharacterChild:midi_projection::call(c,0x2318,0x23bc,true);break;case S::RestoreCharacter:pop(c,6,true);break;default:break;}}
 std::array<T,12>jobs_{};unsigned depth_=0;uint64_t steps_=0;NativeLcdText lcd_;
};
}
